from h34 import *
import math
M=mcq;F=tf;S=short;N=num
b='<rect width="720" height="320" fill="#fffaf0"/><text x="360" y="26" text-anchor="middle" font-size="18" font-weight="bold">A balanced food plate</text>'
cx,cy,r=210,175,120
def pt(a): return cx+r*math.cos(math.radians(a)), cy+r*math.sin(math.radians(a))
secs=[(-90,90,"#9ccf6b","Protective foods"),(90,198,"#f2b36b","Body-building foods"),(198,270,"#f7e07a","Energy foods")]
for a0,a1,col,_ in secs:
    x0,y0=pt(a0);x1,y1=pt(a1);large=1 if a1-a0>180 else 0
    b+=f'<path d="M{cx} {cy} L{x0:.1f} {y0:.1f} A{r} {r} 0 {large} 1 {x1:.1f} {y1:.1f} Z" fill="{col}" stroke="#fff" stroke-width="3"/>'
b+='<text x="275" y="170" text-anchor="middle" font-size="14" font-weight="bold">Most</text><text x="150" y="255" text-anchor="middle" font-size="13" font-weight="bold">Some</text><text x="130" y="140" text-anchor="middle" font-size="13" font-weight="bold">Some</text>'
rows=[("#9ccf6b","Protective foods (most)","fruits and vegetables: carrot, orange, spinach, guava, amla"),("#f2b36b","Body-building foods","pulses, milk, eggs, fish, nuts, soybean"),("#f7e07a","Energy foods (some)","rice, wheat, potato, millets, ghee, oil")]
for i,(c,t,d) in enumerate(rows):
    y=90+i*70
    b+=f'<rect x="380" y="{y}" width="22" height="22" fill="{c}" stroke="#555"/><text x="412" y="{y+17}" font-size="15" font-weight="bold">{t}</text><text x="412" y="{y+38}" font-size="12">{d}</text>'
b+='<text x="360" y="308" text-anchor="middle" font-size="12">Sector sizes show the order of how much to eat, not exact amounts.</text>'
svgfile('c4evs-food-plate.svg',720,320,b)
chapter(4,'evs','food-for-health','Food for Health',
 ('The food festival','The day of the school food festival has come, and the stalls are full of fresh fruits, sprouts, dhokla, dosa, vada, ragi laddu and many other dishes. The children taste, guess ingredients and ask why one dish tastes sweet, salty and bitter all at once. As they visit each stall they learn about the six tastes, millets, the three groups of food, junk food, water and cooking. Let us taste, think and plan a healthy plate.'),
 [('Mystery Masala and the six tastes',['At a stall called Mystery Masala the children tasted a food that was a little sweet, a little salty and a little bitter, and they wondered why it tasted different to each of them.','It was Ugadi Pachadi, a traditional food of Andhra Pradesh, Karnataka and Telangana, made with six taste elements.','The six tastes are sweet, sour, salty, pungent, bitter and astringent.','Examples are jaggery for sweet, tamarind for sour, salt for salty, green chilli for pungent, neem for bitter and raw mango for astringent.','In Ayurveda the six tastes are called shad rasa, and eating balanced food with all six tastes is good for health.']),
  ('Millets, the super food',['Surbhi visited a stall of millet foods and remembered that her grandmother ate jowar and bajra roti in winter and jau roti in summer.','Millets are rich sources of nutrients.','The children enjoyed jowar upma and other millet-based foods, and ragi laddu was on the festival menu too.','You can find out a millet food that is cooked in your own home.']),
  ('How food helps us, the three food groups',['A banner at the festival said Colours on Plate, Wellness in Life, which reminds us to eat a variety of foods.','Our body needs variety to stay healthy, energetic and strong, and no single food has all the nutrients we need.','Energy foods give energy, and they include rice, wheat, potato, maize, banana, honey and millets, and butter, ghee and oil.','Body-building foods help us grow and make our muscles strong, and they include pulses, soybeans, chickpeas, milk, cheese, eggs, fish, meat, nuts and tofu.','Protective foods protect us from diseases, and they include fruits and vegetables like carrot, orange, lemon, papaya, spinach, cabbage, guava, amla and tomato.','If we ate foods from only one group every day, our body would miss the other things it needs.']),
  ('The balanced plate and junk food',['A balanced plate has food from all three groups in the right amounts, with protective foods the most, then body-building foods, and some energy foods.','This helps us stay healthy, active and happy, and every region of India has a thali that mixes foods with different tastes and benefits.','Junk food is food that is not healthy if eaten regularly or in large amounts, because it has a lot of oil, salt and sugar.','Examples are soft drinks, chips, burgers, pizza and over-processed packaged food, and fresh home-cooked food is better.','A food diary for a week helps you see what you eat and which food groups you are missing.']),
  ('Water for health',['Water is an important part of our diet.','Water helps in digesting food and keeps our skin and body healthy.','It also helps to remove waste from the body through urine, sweat and faeces.','Water-rich fruits like watermelon and cucumber also help the body keep water, and drinking enough water should be a healthy habit.']),
  ('Ways of cooking',['The children wondered how the festival dishes were made, and there are different cooking methods.','Idli is steamed, rice and dal are boiled, samosa and vada are fried, papad can be roasted, and cakes and breads are baked.','Some foods like fruit chaat and vegetable salads can be eaten without cooking.','A chef is a professional cook, and the word chef in French means a director or head of the kitchen.','A solar cooker cooks food using sunlight instead of a gas stove or electricity, and it does not produce smoke or ash, so it does not pollute the environment.']),
  ('Reading food labels',['Before buying or eating packaged food, check its label.','A label tells the net weight, the date it was packed and the best before or expiry date, and the main ingredients.','Checking labels protects us from eating spoiled food and helps us choose healthy food.','You can also make a food collage with three sections for energy, body-building and protective foods, and plan your own school food festival.'])],
 [('Sort these foods into the three groups: rice, spinach, milk, banana, guava, egg.',[('Energy foods: rice and banana.','They are rich in energy.'),('Body-building foods: milk and egg.','They help us grow and build muscles.'),('Protective foods: spinach and guava.','Vegetables and fruits protect us from diseases.')]),
  ('A child eats only chips and a soft drink for lunch. What is wrong and what would you change?',[('Chips and soft drinks are junk food with a lot of oil, salt and sugar.','Eaten regularly, they are not healthy.'),('The lunch has no protective foods and no body-building foods.','A balanced plate needs all three groups.'),('Change it to a plate with dal or egg, vegetables, fruit and a little rice or roti, and a glass of water.','This covers all three groups plus water.')])],
 ('Describe a balanced plate and why we need all three food groups.',['Energy foods, body-building foods and protective foods','Protective foods the most, body-building next, some energy foods','No single food has all nutrients','Avoid too much junk food and drink enough water'],['Only sweets give energy so we can eat only sweets','Junk food is a good daily meal','Water is not part of food']),
 ['The six tastes are sweet, sour, salty, pungent, bitter and astringent (shad rasa).','Food groups: energy, body-building and protective foods.','A balanced plate has the most protective foods, then body-building foods, and some energy foods.','Junk food has a lot of oil, salt and sugar and should be avoided regularly.','Drink enough water, check food labels and use different cooking methods.'],
 [M('1',1,'Which of these is a protective food?','Spinach',[('Rice','Rice is an energy food'),('Egg','Egg is a body-building food')],'Fruits and vegetables like spinach protect us from diseases.'),
  M('2',1,'Which group does milk belong to?','Body-building foods',[('Energy foods','Energy foods include rice and potatoes'),('Protective foods','Protective foods are fruits and vegetables')],'Milk helps us grow and build muscles.'),
  M('3',1,'Which taste does jaggery have?','Sweet',[('Bitter','Neem is bitter'),('Sour','Tamarind is sour')],'Jaggery is sweet.'),
  M('4',1,'What are the six tastes together called in Ayurveda?','Shad rasa',[('Panch rasa','Shad means six'),('Tri rasa','Shad means six')],'Shad rasa means the six tastes.'),
  M('5',2,'What is Ugadi Pachadi made with?','Six taste elements',[('Only sugar','It has six tastes'),('Only chilli','It has six tastes')],'It mixes sweet, sour, salty, pungent, bitter and astringent.'),
  M('6',2,'Which part of a balanced plate is the biggest?','Protective foods',[('Energy foods','Energy foods are only some'),('Junk food','Junk food does not belong in a balanced plate')],'Protective foods, fruits and vegetables, are the most.'),
  M('7',2,'Why should we avoid eating junk food regularly?','It has a lot of oil, salt and sugar',[('It is always cold','The problem is oil, salt and sugar'),('It is expensive','The problem is oil, salt and sugar')],'Such food is not healthy in large amounts.'),
  M('8',2,'Which job does water do in the body?','It helps digest food and removes waste',[('It builds bones directly','The chapter says digestion and waste removal'),('It gives all the energy','Energy comes from energy foods')],'Water helps digestion and removes waste through urine, sweat and faeces.'),
  M('9',2,'Which cooking method is used for idli?','Steaming',[('Frying','Samosa and vada are fried'),('Roasting','Roasting is for foods like papad')],'Idli is steamed.'),
  M('10',2,'What does a solar cooker use to cook?','Sunlight',[('Gas','A gas stove uses gas'),('Electricity','A solar cooker uses sunlight')],'It makes no smoke or ash.'),
  F('11',2,'A single food gives all the nutrients our body needs.',False,'No single food has everything, so we need variety.'),
  F('12',3,'We should check the best before date on packaged food.',True,'The label tells us whether the food is safe and fresh.')],
 svgs=[('c4evs-food-plate','A plate split into three sectors: the largest is protective foods, then body-building foods, then energy foods.','A balanced plate has the most protective foods.')],
 keep=['shad rasa','junk food'])
